from pathlib import Path
import json,sys,re
BASE=Path(__file__).resolve().parent
sys.path.insert(0,str(BASE.parent))
from probe import robots_decision
E=BASE/'evidence'
def meta(n):return json.loads((E/(n+'.json')).read_text())
def size(value,unit,date,url,path,quality,note):return dict(value=value,unit=unit,date=date,source_url=url,evidence_path=path,quality=quality,note=note)
def library(slug,name,selection,sz,qtext,count,book,access,match='exact_title',family='Koha',robot=None,issues=None):
 q=meta(slug+'-query');r=meta((robot or slug)+'-robots');d=robots_decision(E/((robot or slug)+'-robots.json'),q['url'])
 row=dict(id='uga-'+slug,name=name,recommendation=selection,scope='One institutional library service; branches are not separate successes',size=sz,platform=dict(family=family,name=family+'; version not established',proof='Observed Koha /cgi-bin/koha/opac-search.pl and bibliographic-detail routes, institutional heading and template.' if family=='Koha' else 'Custom physical-books search page links returned records to the separately hosted Koha OPAC; Koha native search is robots-restricted.',evidence_path=q['evidence_path']),query=dict(text=qtext,method=q['method'],url=q['url'],payload=q['payload'],checked_at_utc=q['checked_at_utc'],http_status=q['status'],effective_url=q['effective_url'],result_count=count,count_note='Search automatically redirects to one bibliographic record; total search count not separately displayed.' if slug=='gulu' else 'Displayed search response count; exact title matching still requires record-level inspection.',match_type=match,evidence_path=q['evidence_path'],metadata_path=q['metadata_path']),books=[book],robots=dict(url=r['url'],status=r['status'],checked_at_utc=r['checked_at_utc'],evidence_path=r['metadata_path'],decision=d['decision'],note=d['note']),reader_access=access,integration=dict(existing_adapter='candidate reuse' if family=='Koha' else 'custom',needs=['Keep biblionumber and edition identity; confirm ISBN separately.','Preserve current/home location, restricted shelving, copy notes and circulation states.','Confirm operator reuse terms and request budget before production.']+(issues or []),blockers=['No live application integration tested; public OPAC access is not a reuse licence.'],live_app_tested=False))
 if slug=='bugema':
  row['robots']['note']+=' Public custom frontend allows /; native bulibrary.bugemauniv.ac.ug search remains explicitly excluded (bugema-robots evidence). No request was made to the excluded search route.'
 if slug=='gulu': row['query']['result_count']=None
 return row
def book(title,author,id,url,isbn,hold,path): return dict(title=title,author=author,record_id=id,record_url=url,isbn=isbn,holdings=hold,evidence_path=path)
