# Remove irrelevant public login strings and signed asset links from saved discovery output.
for path in E.glob('*discovery.json'):
 data=json.loads(path.read_text())
 for item in data.get('content',[]):
  if item.get('type')=='text':
   chunks=item['text'].split('--------------------------------------------------------------------------------')
   chunks=[c for c in chunks if 'mubs.ac.ug/docs/newsletters/September_2015.pdf' not in c and 'X-Amz-Credential=' not in c]
   item['text']='--------------------------------------------------------------------------------'.join(chunks)
 path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
